#include <cstdio>
#include <iostream>
#include <algorithm>
using namespace std;

int a[5],ans[4][4];
bool ok;

void print()  //输出
{
    for (int i=1;i<=3;i++)
    {
    	if (ans[i][1]<ans[i][3])
			swap(ans[i][1],ans[i][3]);  //注意题目中说两个数必须先输出大的再输出小的
        printf("%d",ans[i][1]);  //输出第一个数字
        if (ans[i][2]==1) printf("+");
        if (ans[i][2]==2) printf("-");
        if (ans[i][2]==3) printf("*");
        if (ans[i][2]==4) printf("/");  //输出运算符号
        printf("%d",ans[i][3]);
        if (ans[i][2]==1) printf("=%d\n",ans[i][1]+ans[i][3]);
        if (ans[i][2]==2) printf("=%d\n",ans[i][1]-ans[i][3]);
        if (ans[i][2]==3) printf("=%d\n",ans[i][1]*ans[i][3]);
        if (ans[i][2]==4) printf("=%d\n",ans[i][1]/ans[i][3]);  //输出结果
    }
}

bool check()  //判断是否组成了24
{
    for (int i=1;i<=4;i++)
        if (a[i]==24) return 1;
    return 0;
}

void dfs(int k)
{
    if (k==4)  //搜索完毕
    {
        if (check())
        {
            print();
            ok=1;
        }
        return;
    }
    int x,y;
    for (int i=1;i<=4;i++)
        for (int j=1;j<=4;j++)  //枚举两个数字
            if (i!=j&&a[i]>0&&a[j]>0)
            {
                ans[k][1]=a[i];  //加
                ans[k][2]=1;
                ans[k][3]=a[j];
                x=a[i],y=a[j];
                a[i]=x+y;
                a[j]=-1;
                dfs(k+1);
                a[i]=x;
                a[j]=y;
                if (ok) return;

                ans[k][1]=a[i];  //减
                ans[k][2]=2;
                ans[k][3]=a[j];
                x=a[i],y=a[j];
                a[i]=x-y;
                a[j]=-1;
                dfs(k+1);
                a[i]=x;
                a[j]=y;
                if (ok) return;

                ans[k][1]=a[i];  //乘
                ans[k][2]=3;
                ans[k][3]=a[j];
                x=a[i],y=a[j];
                a[i]=x*y;
                a[j]=-1;
                dfs(k+1);
                a[i]=x;
                a[j]=y;
                if (ok) return;

                if (a[j]>0&&a[i]%a[j]==0)  //除，注意要判断能否整除
                {
                    ans[k][1]=a[i];
                    ans[k][2]=4;
                    ans[k][3]=a[j];
                    x=a[i],y=a[j];
                    a[i]=x/y;
                    a[j]=-1;
                    dfs(k+1);
                    a[i]=x;
                    a[j]=y;
                    if (ok) return;
                }
            }
}

int main()
{
    scanf("%d%d%d%d",&a[1],&a[2],&a[3],&a[4]);
    dfs(1);
    if (!ok) cout<<"No answer!";
    return 0;
}
